function showAudioState(message=''){$('#storyDuration').textContent=audioState.seconds?`${clockDuration(audioState.seconds)} · ${Math.ceil(audioState.seconds/60)} мин`:audioState.status==='loading'?'Уншиж байна…':'Аудио оруулаагүй';$('#audioMeasureStatus').textContent=message||(audioState.seconds?'Бүтэн аудионы бодит хугацаа · автоматаар':'URL оруулсны дараа автоматаар шалгана.');$('#measureAudio').disabled=audioState.status==='loading'}
function resetAudio(url='',seconds=0){clearTimeout(audioProbeTimer);audioToken++;seconds=url?(Number(seconds)||0):0;audioState={url,seconds,status:seconds?'ready':'empty',promise:null};showAudioState()}
async function probeFullAudio(force=false){
 const raw=$('#storyAudioFull').value.trim(),url=safeUrl(raw);if(!raw){resetAudio();return true}if(!url){resetAudio();audioState.status='error';showAudioState('Зөв HTTPS эсвэл localhost аудио URL оруулна уу.');return false}
 if(!force&&audioState.url===url&&audioState.seconds>0)return true;
 if(!force&&audioState.url===url&&audioState.promise)return audioState.promise;
 const token=++audioToken;audioState={url,seconds:0,status:'loading',promise:null};showAudioState();
 const promise=audioPreview(url).then(source=>measureAudio(source)).then(seconds=>{if(token!==audioToken)return false;audioState={url,seconds,status:'ready',promise:null};showAudioState();markStory();return true}).catch(e=>{if(token!==audioToken)return false;audioState={url,seconds:0,status:'error',promise:null};showAudioState(e.message);return false});audioState.promise=promise;return promise;
}
$('#storyAudioFull').addEventListener('input',()=>{if(safeUrl($('#storyAudioFull').value)!==audioState.url)resetAudio();syncAudioSource($('#storyAudioFull').value);markStory();clearTimeout(audioProbeTimer);audioProbeTimer=setTimeout(()=>probeFullAudio(),650)});$('#storyAudioFull').addEventListener('change',()=>{syncAudioSource($('#storyAudioFull').value);probeFullAudio()});$('#measureAudio').addEventListener('click',()=>probeFullAudio(true));
const segmentStatus=$('#audioSegmentStatus'),sourcePlayer=$('#audioSourcePlayer');let audioSourceToken=0,cropPollTimer=null,cropJobId=null;
async function syncAudioSource(raw){const token=++audioSourceToken,url=safeUrl(raw);sourcePlayer.pause();sourcePlayer.ontimeupdate=null;if(!url){sourcePlayer.removeAttribute('src');sourcePlayer.hidden=true;return}try{const playable=await audioPreview(url);if(token!==audioSourceToken)return;sourcePlayer.src=playable;sourcePlayer.hidden=false;sourcePlayer.load();segmentStatus.textContent='Бүтэн аудиог энэ player дээр сонсож, IN / OUT цэгээ сонгоно.'}catch{if(token===audioSourceToken)segmentStatus.textContent='Аудиог нээж чадсангүй. URL эсвэл хувийн сангийн эрхийг шалгана уу.'}}
sourcePlayer.addEventListener('loadedmetadata',()=>{if(Number.isFinite(sourcePlayer.duration)){audioState.seconds=sourcePlayer.duration;showAudioState();const end=$('#storyPreviewEnd');if(parseClockTime(end.value)>sourcePlayer.duration)end.value=clockDuration(Math.floor(sourcePlayer.duration))}});
function selectedRange(){const start=parseClockTime($('#storyPreviewStart').value),end=parseClockTime($('#storyPreviewEnd').value);if(!Number.isFinite(start)||!Number.isFinite(end)||start<0||end-start<5||end-start>180)throw Error('Preview хэсэг 5 секундээс 3 минутын хооронд байна.');if(Number.isFinite(sourcePlayer.duration)&&end>sourcePlayer.duration)throw Error(`Бүтэн аудио ${Math.floor(sourcePlayer.duration)} секунд байна.`);return{start,end}}
let playSelectedRange=false;
sourcePlayer.addEventListener('timeupdate',()=>{if(!playSelectedRange)return;const end=parseClockTime($('#storyPreviewEnd').value);if(Number.isFinite(end)&&sourcePlayer.currentTime>=end){playSelectedRange=false;sourcePlayer.pause();sourcePlayer.currentTime=end;segmentStatus.textContent=`${clockDuration(parseClockTime($('#storyPreviewStart').value))}–${clockDuration(end)} сонголт дууслаа.`}});
$('#playAudioSegment').addEventListener('click',async()=>{try{if(!sourcePlayer.src)throw Error('Бүтэн аудио URL оруулсны дараа сонсоно уу.');const{start,end}=selectedRange();if(sourcePlayer.readyState<1)await new Promise((resolve,reject)=>{const timer=setTimeout(()=>reject(Error('Аудионы хугацааг уншиж чадсангүй.')),12000);sourcePlayer.addEventListener('loadedmetadata',()=>{clearTimeout(timer);resolve()},{once:true});sourcePlayer.addEventListener('error',()=>{clearTimeout(timer);reject(Error('Бүтэн аудиог нээж чадсангүй.'))},{once:true})});if(end>sourcePlayer.duration)throw Error(`Бүтэн аудио ${Math.floor(sourcePlayer.duration)} секунд байна.`);playSelectedRange=true;sourcePlayer.currentTime=start;await sourcePlayer.play();segmentStatus.textContent=`${clockDuration(start)}–${clockDuration(end)} сонголтыг сонсож байна.`}catch(error){playSelectedRange=false;segmentStatus.textContent=error.message||'Аудионы хэсгийг тоглуулж чадсангүй.'}});
