$$('[data-preview-view]').forEach(select=>{select.value=previewViews[select.dataset.previewView];select.addEventListener('change',()=>{previewViews[select.dataset.previewView]=select.value;queuePreviews()})});
let layoutDrag=null,layoutDragFrame=0;
function applyLayoutDrag(){layoutDragFrame=0;const d=layoutDrag;if(!d?.pending)return;const {x,y}=d.pending,dx=x-d.x,dy=y-d.y;d.live={x:d.overflowX?Math.max(0,Math.min(100,d.crop.x-dx/d.overflowX*100)):d.crop.x,y:d.overflowY?Math.max(0,Math.min(100,d.crop.y-dy/d.overflowY*100)):d.crop.y};const source=setCrop(d.scope,d.live),frame=$(`[data-preview-frame="${d.scope}"]`);if(d.scope==='story')imagePreview('story');frame?.contentWindow?.postMessage({type:'adult-studio-crop-live',scope:d.scope,storyId:editing?.id||'studio-draft',crop:visualFor({visual_theme:themeDraft},source,cropDevices[d.scope]==='mobile')},location.origin)}
function beginCropDrag(scope,x,y,width,height,naturalWidth,naturalHeight){const source=scope==='story'?storyOverlay:homeOverlay,crop=cropFor(source,cropDevices[scope]==='mobile'),ratio=(crop.fit==='contain'?Math.min:Math.max)(width/naturalWidth,height/naturalHeight);layoutDrag={scope,x,y,crop,live:{x:crop.x,y:crop.y},overflowX:Math.max(0,naturalWidth*ratio*crop.zoom-width),overflowY:Math.max(0,naturalHeight*ratio*crop.zoom-height)}}
let layoutDragFromCard=false;const cardCrop=$('#storyImagePreview');cardCrop.addEventListener('pointerdown',event=>{const img=cardCrop.querySelector('img');if(!img?.naturalWidth)return;const box=cardCrop.getBoundingClientRect();layoutDragFromCard=true;cardCrop.classList.add('dragging');try{cardCrop.setPointerCapture(event.pointerId)}catch{}beginCropDrag('story',event.clientX,event.clientY,box.width,box.height,img.naturalWidth,img.naturalHeight);event.preventDefault()});
cardCrop.addEventListener('pointermove',event=>{if(!layoutDragFromCard||!layoutDrag)return;layoutDrag.pending={x:event.clientX,y:event.clientY};if(!layoutDragFrame)layoutDragFrame=requestAnimationFrame(applyLayoutDrag)});
cardCrop.addEventListener('pointerup',event=>{if(!layoutDragFromCard||!layoutDrag)return;layoutDrag.pending={x:event.clientX,y:event.clientY};applyLayoutDrag();const d=layoutDrag;layoutDrag=null;layoutDragFromCard=false;cardCrop.classList.remove('dragging');if(d.live.x!==d.crop.x||d.live.y!==d.crop.y)updateCrop('story',{x:d.live.x,y:d.live.y})});
window.addEventListener('message',event=>{if(event.origin!==location.origin)return;const frame=$$('[data-preview-frame]').find(f=>f.contentWindow===event.source);if(event.data?.type==='adult-studio-ready'&&frame){frame.dataset.ready='yes';queuePreviews();return}const m=event.data;if(!frame||m?.type!=='adult-studio-crop-drag'||!['story','home'].includes(m.scope))return;if(m.phase==='start'){beginCropDrag(m.scope,m.x,m.y,m.width,m.height,m.naturalWidth,m.naturalHeight);return}if(m.phase==='end'){const d=layoutDrag;if(d?.scope===m.scope){d.pending={x:m.x,y:m.y};applyLayoutDrag();layoutDrag=null;if(d.live.x!==d.crop.x||d.live.y!==d.crop.y)updateCrop(d.scope,{x:d.live.x,y:d.live.y})}return}if(m.phase==='move'&&layoutDrag?.scope===m.scope){layoutDrag.pending={x:m.x,y:m.y};if(!layoutDragFrame)layoutDragFrame=requestAnimationFrame(applyLayoutDrag)}});
const previewObserver=new ResizeObserver(()=>{for(const scope of ['story','home','design'])fitPreview(scope)});$$('.preview-stage').forEach(stage=>previewObserver.observe(stage));
window.addEventListener('beforeunload',e=>{if(storyDirty||homeDirty||themeDirty||settingsDirty){e.preventDefault();e.returnValue=''}});
function fillSettings(){let s=data.site;$('#settingBrand').value=s.brand||'';$('#settingCategories').value=(s.categories||[]).join('\n');renderCategoryManager();$('#settingMembership').value=s.membership_price||29900;$('#settingMembershipList').value=s.membership_list_price||34900;$('#settingMembershipFirst').value=s.membership_first_price||24900;$('#settingMembershipWeek').value=s.membership_week_price||9900;$('#settingAnnouncement').value=s.announcement||'';$('#settingSeoTitle').value=s.seo_title||'';$('#settingSeoDescription').value=s.seo_description||'';$('#settingCloudName').value=s.cloudinary_name||CONFIG.cloudName||'';$('#settingPreset').value=s.upload_preset||CONFIG.unsignedUploadPreset||''}
$('#saveSettings').addEventListener('click',async()=>{try{let s={...data.site,brand:$('#settingBrand').value,categories:[...new Set($('#settingCategories').value.split('\n').map(x=>x.trim()).filter(Boolean))],membership_price:Math.max(0,Number($('#settingMembership').value)||0),membership_list_price:Math.max(0,Number($('#settingMembershipList').value)||0),membership_first_price:Math.max(0,Number($('#settingMembershipFirst').value)||0),membership_week_price:Math.max(0,Number($('#settingMembershipWeek').value)||0),announcement:$('#settingAnnouncement').value,seo_title:$('#settingSeoTitle').value,seo_description:$('#settingSeoDescription').value,cloudinary_name:$('#settingCloudName').value.trim(),upload_preset:$('#settingPreset').value.trim()};if(!/^[\w-]+$/.test(s.cloudinary_name))throw Error('Cloud name буруу байна');CONFIG.cloudName=s.cloudinary_name;CONFIG.unsignedUploadPreset=s.upload_preset;await saveSite(s);settingsDirty=false;await reload();fillCategories($('#storyCategory').value);toast('Системийн тохиргоо хадгалагдлаа')}catch(e){toast(e.message,true)}});
function downloadFile(name,text){let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type:'application/json'}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1500)}
$('#exportBackup').addEventListener('click',async()=>{try{working('Backup бэлдэж байна...');let b=JSON.parse(JSON.stringify(data));b.bodies=[];for(let s of b.stories)b.bodies.push(await getBody(s.id));downloadFile('adult-stories-cms-backup-'+new Date().toISOString().slice(0,10)+'.json',JSON.stringify({...b,export_version:6,exported_at:new Date().toISOString()},null,2));working('Backup бэлэн');toast('JSON backup татагдлаа')}catch(e){toast(e.message,true)}});
$('#importBackup').addEventListener('change',async e=>{const f=e.target.files[0];if(!f)return;try{let raw=JSON.parse(await f.text());if(!Array.isArray(raw.stories)||!Array.isArray(raw.assets)||!raw.site)throw Error('Backup JSON формат буруу');pendingImport=raw;toast(`${raw.stories.length} өгүүллэг, ${raw.assets.length} зурагтай backup уншлаа.`)}catch(err){toast(err.message,true)}});
$('#performImport').addEventListener('click',async()=>{
 if(!pendingImport)return toast('Эхлээд backup файл сонгоно уу',true);
 const backup=pendingImport,homepage=!!$('#importHomepage')?.checked,button=$('#performImport');
 if(!confirm(online?`${backup.stories.length} өгүүллэг, ${backup.assets.length} зургийг Supabase руу нэмэх үү? Ижил холбоостой одоогийн өгүүллэгийг алгасна. ${homepage?'Нүүр хуудасны дизайн, тохиргоог backup-аар солино.':'Нүүр хуудасны тохиргоог хэвээр үлдээнэ.'}`:'Одоогийн локал контентыг backup-оор солих уу?'))return;
 button.disabled=true;
 try{
  if(online){const result=await importCloudBackup(backup,{homepage,onProgress:working});toast(`${result.stories} өгүүллэг, ${result.assets} зураг нэмлээ. ${result.skipped} өгүүллэг алгассан.`)}
  else{await importLocalBackup(backup);toast('Локал backup импорт амжилттай')}
  pendingImport=null;storyDirty=false;await reload({reset:true});newStory({force:true});working('Импорт дууслаа');
 }catch(error){working('Импорт зогслоо. Нэмэгдсэн зүйлс хадгалагдсан; ижил backup-аар дахин оролдож болно.');toast(error.message,true)}finally{button.disabled=false}
});
$('#adminNav').addEventListener('click',e=>{let b=e.target.closest('[data-tab]');if(b)setTab(b.dataset.tab)});$('#refreshBtn').addEventListener('click',async()=>{try{if((homeDirty||themeDirty||settingsDirty)&&!confirm('Хадгалаагүй сайтын тохиргоог орхиод серверээс шинэчлэх үү?'))return;await reload({reset:true});toast('Серверээс шинэчиллээ')}catch(e){toast(e.message,true)}});
$('#logoutBtn').addEventListener('click',async()=>{if(online){await signOut();$('#appRoot').classList.add('hidden');$('#loginWrap').classList.remove('hidden')}else location.href='index.html'+(CONFIG.localContentMode?'?local=1':'')});
$$('[data-editor-tab]').forEach((button,index)=>button.addEventListener('keydown',event=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(event.key))return;event.preventDefault();const tabs=$$('[data-editor-tab]'),next=event.key==='Home'?0:event.key==='End'?tabs.length-1:(index+(event.key==='ArrowRight'?1:tabs.length-1))%tabs.length;tabs[next].focus();setEditorTab(tabs[next].dataset.editorTab)}));
$('#loginBtn').addEventListener('click',login);$('#loginPassword').addEventListener('keydown',e=>{if(e.key==='Enter')login()});
async function login(){try{$('#loginError').classList.add('hidden');working('Нэвтэрч байна...');await signIn($('#loginEmail').value,$('#loginPassword').value);if(!await isAdmin()){await signOut();throw Error('Энэ хэрэглэгч admin_users бүртгэлд алга.');}$('#loginWrap').classList.add('hidden');$('#appRoot').classList.remove('hidden');await reload();newStory()}catch(e){$('#loginError').textContent=e.message;$('#loginError').classList.remove('hidden')}}
$$('[data-section="settings"] input,[data-section="settings"] textarea').forEach(el=>el.addEventListener('input',()=>{settingsDirty=true}));
mediaWorkspace=createMediaWorkspace({
 data:()=>data,theme:()=>themeDraft,editor:()=>({id:editing?.id,token:editToken,title:$('#storyTitle').value}),value:scope=>$(scope==='story'?'#storyCover':'#homeImage').value,
 toast,original:showOriginal,reload,download:downloadFile,
 select:(scope,id)=>{const input=$(scope==='story'?'#storyCover':'#homeImage');input.value=id||'';imagePreview(scope);if(scope==='story')markStory();else{homeDirty=true;queuePreviews()}},
 assigned:(kind,id,assetId)=>{if(kind==='home'){$('#homeImage').value=assetId||'';imagePreview('home')}else if(editing?.id===id){editing.cover_id=assetId;$('#storyCover').value=assetId||'';imagePreview('story')}queuePreviews()},
 removed:id=>{if($('#storyCover').value===id){$('#storyCover').value='';if(editing)editing.cover_id=null;imagePreview('story')}if($('#homeImage').value===id){$('#homeImage').value='';imagePreview('home')}},
 reordered:ids=>{if(editing&&ids.includes(editing.id)){editing.sort_order=ids.indexOf(editing.id)+1;$('#storyOrder').value=editing.sort_order}},
 openCover:()=>{setTab('stories');setEditorTab('cover')}
});
mountR2({reload,toast,editorToken:()=>editToken,onAudio:reference=>{if(!bodyReady)return toast('Өгүүллэгийн агуулга ачаалж дуусахыг хүлээнэ үү.',true);$('#storyAudioFull').value=reference;resetAudio();syncAudioSource(reference);markStory();probeFullAudio(true)}});
window.addEventListener('keydown',event=>{
 if(storySaving){if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='s')event.preventDefault();return}
 if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='s'){event.preventDefault();if(document.querySelector('dialog[open]'))return;const button={stories:'saveStory',homepage:'saveHomepage',design:'saveDesign',settings:'saveSettings'}[active];if(button)$('#'+button).click();else toast('Хадгалах өөрчлөлт энэ хэсэгт алга.');}
 if(event.key==='/'&&!event.ctrlKey&&!event.metaKey&&!event.target.closest('input,textarea,select,[contenteditable=true]')){const search=active==='media'?$('#mediaSearch'):active==='stories'?$('#storyListSearch'):null;if(search){event.preventDefault();search.focus()}}
 if(event.key==='Escape'){$('#lightbox').classList.add('hidden');$('#assetEditModal').classList.add('hidden')}
});
async function boot(){if(!online){$('#appRoot').classList.remove('hidden');await reload();newStory();return}try{let s=await session();if(s&&await isAdmin()){$('#appRoot').classList.remove('hidden');await reload();newStory()}else{$('#loginWrap').classList.remove('hidden')}}catch(e){$('#loginWrap').classList.remove('hidden');$('#loginError').textContent='Холболт амжилтгүй: '+e.message;$('#loginError').classList.remove('hidden')}}

const draftFields=['storyTitle','storySeriesTitleInput','storySeriesOrderInput','storyExcerpt','storyPreview','storyFull','storyTags','storyAudioPreview','storyAudioFull','storyPrice','storyOrder','storyStatus','storyCategory','storyCover','storyIndexReads','storyIndexReadsCustom','storyIndexListens','storyPreviewStart','storyPreviewEnd'];
const drafts=createDrafts({key:()=>editing?.id||'new',ready:()=>bodyReady&&storyDirty&&!!data,capture:()=>({fields:Object.fromEntries(draftFields.map(id=>[id,$('#'+id).value])),overlay:storyOverlay,audio_seconds:audioState.seconds,base_updated_at:editing?.updated_at||null}),restore:payload=>{if(!bodyReady)return toast('Агуулга ачаалж дуусахыг хүлээнэ үү.',true);for(const id of draftFields)if(payload.fields?.[id]!==undefined)$('#'+id).value=payload.fields[id];controlsSet('story',payload.overlay||overlayDefault());resetAudio(safeUrl($('#storyAudioFull').value),payload.audio_seconds);storyDirty=true;updateStoryMeta();queuePreviews()},onError:message=>toast(message,true)});

window.addEventListener('pagehide',()=>drafts.flushLocal());
try{await boot()}catch(e){
 console.error('Adult Stories admin startup failed:',e);
 const help=$('#openHelp');
 if(help){
  help.style.display='grid';
  help.setAttribute('aria-live','assertive');
  help.querySelector('h1').textContent='Admin студиог ачаалж чадсангүй';
  help.querySelectorAll('p')[0].textContent='Ачаалалтын үед алдаа гарлаа. Тохиргоо болон холболтоо шалгаад хуудсыг дахин ачаална уу.';
  const detail=document.createElement('p');detail.className='small';detail.textContent=e?.message||String(e);help.querySelector('.open-help-card').append(detail);
 }
}

function renderCategoryManager(){
 const list=$('#categoryManagerList');if(!list)return;const values=[...new Set($('#settingCategories').value.split('\n').map(v=>v.trim()).filter(Boolean))];
 list.innerHTML=values.map((value,index)=>`<span class="category-chip">${esc(value)}<button type="button" data-category-remove="${index}" aria-label="${esc(value)} ангиллыг хасах">×</button></span>`).join('')||'<span class="small">Ангилал нэмээгүй байна.</span>';
}
$('#categoryManagerList')?.addEventListener('click',event=>{const button=event.target.closest('[data-category-remove]');if(!button)return;const values=$('#settingCategories').value.split('\n').map(v=>v.trim()).filter(Boolean);values.splice(Number(button.dataset.categoryRemove),1);$('#settingCategories').value=values.join('\n');settingsDirty=true;renderCategoryManager()});
function addCategory(){const input=$('#newCategoryName'),value=input.value.trim().slice(0,60);if(!value)return;const values=$('#settingCategories').value.split('\n').map(v=>v.trim()).filter(Boolean);if(values.some(v=>v.toLowerCase()===value.toLowerCase()))return toast('Энэ ангилал байна.',true);values.push(value);$('#settingCategories').value=values.join('\n');input.value='';settingsDirty=true;renderCategoryManager();input.focus()}
$('#addCategoryButton')?.addEventListener('click',addCategory);$('#newCategoryName')?.addEventListener('keydown',event=>{if(event.key==='Enter'){event.preventDefault();addCategory()}});
